#!/bin/bash
docker exec broker_app node -e 'const p = require("./src/services/database"); (async () => { const t = await p.tenant.findMany({include:{configuration:true}}); console.log("\n=== WEBHOOK SYNC CHECK ==="); for(const x of t) { console.log("\nTenant: " + x.name); console.log("  waPhoneId: " + (x.waPhoneId || "NULL")); if(x.configuration) { console.log("  phoneNumberId: " + (x.configuration.phoneNumberId || "NULL")); console.log("  SYNC? " + (x.waPhoneId === x.configuration.phoneNumberId ? "OK" : "FAIL")); } else { console.log("  Config: MISSING"); } } process.exit(0); })();'
